/**
 * Shared helper that builds an isolated fake `qodercli` installation for tests.
 *
 * `createQoderFixture(t, options)` creates a temp directory under /tmp with:
 *   - `<dir>/qodercli`            executable POSIX sh wrapper (spawn it directly,
 *                                 with an args array and no shell)
 *   - `<dir>/state/control.json`  behaviour switch, mutate via `fixture.setControl`
 *   - `<dir>/state/invocations/`  one `<n>.json` record per invocation
 *   - `<dir>/state/sessions/`     one `<id>.json` per Qoder session
 *
 * The wrapper runs the same Node executable that runs the tests, so the fixture
 * works with source adapters that call `child_process.spawn(executable, args)`.
 * It never uses the network and never reads the user's home directory or Qoder
 * credentials.
 *
 * Typical use from an adapter test:
 *
 *   const fixture = await createQoderFixture(t);
 *   await fixture.setControl({ mode: 'error_during_execution' });
 *   const result = await runAdapter({ qoderExecutable: fixture.executable });
 *   assert.match((await fixture.invocations())[0].stdin, /prompt/);
 */
import { spawn } from 'node:child_process';
import { chmod, mkdir, mkdtemp, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import { existsSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { CONTROL_DEFAULTS, DEFAULT_MODELS, VERSION, sessionFileName } from './qoder-cli.mjs';

const fixturesDirectory = dirname(fileURLToPath(import.meta.url));

/** Absolute path of the fake CLI program. */
export const QODER_CLI_PATH = join(fixturesDirectory, 'qoder-cli.mjs');
/** The Qoder CLI version the fixture emulates. */
export const QODER_FIXTURE_VERSION = VERSION;
/** The exact model catalogue printed by `--list-models` in text mode. */
export const DEFAULT_QODER_MODELS = DEFAULT_MODELS;
/** Exact stderr text of the real CLI when no account is logged in. */
export const QODER_LOGIN_MESSAGE = 'Not logged in. Run `qodercli login` to authenticate.';

const sleep = milliseconds => new Promise(resolvePromise => setTimeout(resolvePromise, milliseconds));

function shellQuote(value) {
  return `'${String(value).replace(/'/g, "'\\''")}'`;
}

function mergeControl(base, patch) {
  if (!patch || typeof patch !== 'object') return { ...base };
  const merged = { ...base, ...patch };
  if (patch.usage && typeof patch.usage === 'object') merged.usage = { ...(base.usage ?? {}), ...patch.usage };
  return merged;
}

function makeMatcher(test) {
  if (typeof test === 'string') return line => line.includes(test);
  if (test instanceof RegExp) return line => test.test(line);
  if (typeof test === 'function') return test;
  throw new TypeError('waitForLine expects a string, a RegExp or a predicate function');
}

/**
 * @param {import('node:test').TestContext | undefined} t node:test context used
 *   for automatic cleanup. Pass `undefined` and call `fixture.cleanup()`.
 * @param {object} [options]
 * @param {string} [options.tmpRoot='/tmp'] parent directory for the fixture.
 * @param {string} [options.prefix='cta-qoder-fixture-'] temp dir name prefix.
 * @param {object} [options.control={}] initial control file contents.
 * @param {Record<string,string>} [options.env={}] extra env exported by the wrapper.
 * @param {string} [options.nodePath=process.execPath] Node binary run by the wrapper.
 * @param {string} [options.cwd] working directory used when spawning the fixture.
 * @param {boolean} [options.keep] skip automatic cleanup registration.
 */
export async function createQoderFixture(t, options = {}) {
  const root = options.dir ?? await mkdtemp(join(options.tmpRoot ?? '/tmp', options.prefix ?? 'cta-qoder-fixture-'));
  const stateDir = join(root, 'state');
  const invocationsDir = join(stateDir, 'invocations');
  const sessionsDir = join(stateDir, 'sessions');
  await mkdir(invocationsDir, { recursive: true });
  await mkdir(sessionsDir, { recursive: true });

  const controlFile = join(stateDir, 'control.json');
  let control = mergeControl({}, options.control ?? {});
  await writeFile(controlFile, `${JSON.stringify(control, null, 2)}\n`);

  const nodePath = options.nodePath ?? process.execPath;
  const executable = join(root, 'qodercli');
  const wrapperEnv = { QODER_FIXTURE_STATE_DIR: stateDir, ...(options.env ?? {}) };
  const wrapperLines = [
    '#!/bin/sh',
    '# Generated by test/fixtures/qoder-cli-fixture.mjs: fake qodercli (Qoder CLI 1.1.78 surface).',
    ...Object.entries(wrapperEnv)
      .filter(([, value]) => value !== undefined && value !== null)
      .map(([key, value]) => `export ${key}=${shellQuote(value)}`),
    `exec ${shellQuote(nodePath)} ${shellQuote(QODER_CLI_PATH)} "$@"`,
    ''
  ];
  await writeFile(executable, wrapperLines.join('\n'), 'utf8');
  await chmod(executable, 0o755);

  const children = new Set();
  let cleaned = false;

  const spawnOptions = extraEnv => ({
    cwd: options.cwd,
    env: { ...process.env, ...extraEnv },
    stdio: ['pipe', 'pipe', 'pipe']
  });

  const trackChild = child => {
    children.add(child);
    child.once('close', () => children.delete(child));
    child.stdin.on('error', () => {}); // stdout/stderr of a cancelled child may already be closed
    return child;
  };

  /** Run the fixture to completion and collect its output. */
  async function run(args = [], runOptions = {}) {
    const { stdin = '', env = {}, timeoutMs = 10000 } = runOptions;
    const child = trackChild(spawn(executable, args, spawnOptions(env)));
    let stdout = '';
    let stderr = '';
    let settled = false;
    return new Promise((resolvePromise, rejectPromise) => {
      const timer = setTimeout(() => {
        if (settled) return;
        child.kill('SIGKILL');
        rejectPromise(new Error(
          `qoder fixture timed out after ${timeoutMs}ms for args ${JSON.stringify(args)}\nstdout:\n${stdout}\nstderr:\n${stderr}`
        ));
      }, timeoutMs);
      child.stdout.setEncoding('utf8');
      child.stderr.setEncoding('utf8');
      child.stdout.on('data', chunk => { stdout += chunk; });
      child.stderr.on('data', chunk => { stderr += chunk; });
      child.on('error', error => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        rejectPromise(error);
      });
      child.on('close', (code, signal) => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        resolvePromise({ code, signal, stdout, stderr, args: [...args] });
      });
      if (stdin !== null) child.stdin.end(stdin);
      else child.stdin.end();
    });
  }

  /** Spawn the fixture and interact with the live child (cancellation, hangs). */
  function spawnCli(args = [], spawnOptionsArg = {}) {
    const { stdin, env = {} } = spawnOptionsArg;
    const child = trackChild(spawn(executable, args, spawnOptions(env)));
    const state = { stdout: '', stderr: '', lines: [] };
    let pending = '';
    const waiters = new Set();

    const rejectWaiters = reason => {
      for (const waiter of [...waiters]) {
        waiters.delete(waiter);
        clearTimeout(waiter.timer);
        waiter.reject(new Error(
          `${reason}\nstdout:\n${state.stdout}\nstderr:\n${state.stderr}`
        ));
      }
    };

    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');
    child.stdout.on('data', chunk => {
      state.stdout += chunk;
      pending += chunk;
      let newline = pending.indexOf('\n');
      while (newline >= 0) {
        const line = pending.slice(0, newline);
        pending = pending.slice(newline + 1);
        state.lines.push(line);
        for (const waiter of [...waiters]) {
          if (!waiter.matcher(line)) continue;
          waiters.delete(waiter);
          clearTimeout(waiter.timer);
          waiter.resolve(line);
        }
        newline = pending.indexOf('\n');
      }
    });
    child.stderr.on('data', chunk => { state.stderr += chunk; });

    const exited = new Promise(resolvePromise => {
      child.once('close', (code, signal) => {
        rejectWaiters(`qoder fixture exited (code ${code}, signal ${signal}) before the expected output`);
        resolvePromise({ code, signal, stdout: state.stdout, stderr: state.stderr });
      });
    });
    child.on('error', () => {});

    if (stdin !== undefined && stdin !== null) child.stdin.end(stdin);

    const handle = {
      child,
      args: [...args],
      stdout: () => state.stdout,
      stderr: () => state.stderr,
      lines: () => state.lines.slice(),
      write(chunk) { child.stdin.write(chunk); },
      end(chunk) { child.stdin.end(chunk); },
      kill(signal = 'SIGINT') { child.kill(signal); },
      exited,
      async waitForLine(test, waitOptions = {}) {
        const { timeoutMs = 5000, label } = waitOptions;
        const matcher = makeMatcher(test);
        for (const line of state.lines) if (matcher(line)) return line;
        return new Promise((resolvePromise, rejectPromise) => {
          const waiter = { matcher, resolve: resolvePromise, reject: rejectPromise, timer: null };
          waiter.timer = setTimeout(() => {
            waiters.delete(waiter);
            rejectPromise(new Error(
              `timed out after ${timeoutMs}ms waiting for ${label ?? 'a fixture output line'}\nstdout:\n${state.stdout}\nstderr:\n${state.stderr}`
            ));
          }, timeoutMs);
          waiters.add(waiter);
        });
      },
      async result() {
        return exited;
      }
    };
    return handle;
  }

  /** Parsed invocation records, oldest first. */
  async function invocations() {
    const files = (await readdir(invocationsDir).catch(() => []))
      .filter(file => /^\d+\.json$/.test(file))
      .sort((left, right) => Number.parseInt(left, 10) - Number.parseInt(right, 10));
    const records = [];
    for (const file of files) {
      const path = join(invocationsDir, file);
      try {
        records.push({ ...JSON.parse(await readFile(path, 'utf8')), file: path, index: Number.parseInt(file, 10) });
      } catch (error) {
        records.push({ file: path, index: Number.parseInt(file, 10), parseError: error.message });
      }
    }
    return records;
  }

  async function waitForInvocations(count, waitOptions = {}) {
    const { timeoutMs = 5000 } = waitOptions;
    const deadline = Date.now() + timeoutMs;
    for (;;) {
      const records = await invocations();
      if (records.length >= count) return records;
      if (Date.now() > deadline) throw new Error(`timed out waiting for ${count} qoder fixture invocation(s); saw ${records.length}`);
      await sleep(25);
    }
  }

  /** Best effort: resolve once the invocation count stopped changing. */
  async function waitForIdle(waitOptions = {}) {
    const { quietMs = 150, timeoutMs = 5000 } = waitOptions;
    const deadline = Date.now() + timeoutMs;
    let lastCount = null;
    let stableSince = Date.now();
    for (;;) {
      const count = (await invocations()).length;
      if (count !== lastCount) {
        lastCount = count;
        stableSince = Date.now();
      } else if (Date.now() - stableSince >= quietMs) {
        return { count };
      }
      if (Date.now() > deadline) throw new Error(`timed out waiting for the qoder fixture to go idle (last count ${lastCount})`);
      await sleep(25);
    }
  }

  /** Parsed session records, oldest first. */
  async function sessions() {
    const files = (await readdir(sessionsDir).catch(() => [])).filter(file => file.endsWith('.json')).sort();
    const records = [];
    for (const file of files) {
      const path = join(sessionsDir, file);
      try {
        records.push(JSON.parse(await readFile(path, 'utf8')));
      } catch {
        // A session file that is being rewritten by a live fixture is not fatal.
      }
    }
    return records;
  }

  /** Read the persisted state of one Qoder session. */
  async function readSession(sessionId) {
    return JSON.parse(await readFile(join(sessionsDir, sessionFileName(sessionId)), 'utf8'));
  }

  /**
   * Merge a patch into `<stateDir>/control.json`; the next spawn sees it.
   * Deliberately synchronous (it returns the control, not a promise) so a test
   * can call it immediately before spawning without racing the file write.
   */
  function setControl(patch = {}) {
    if (cleaned) throw new Error('qoder fixture has already been cleaned up');
    control = mergeControl(control, patch);
    writeFileSync(controlFile, `${JSON.stringify(control, null, 2)}\n`);
    return { ...control };
  }

  function getControl() {
    return { ...control };
  }

  /** Remove the temp directory (idempotent). */
  async function cleanup() {
    if (cleaned) return;
    cleaned = true;
    for (const child of [...children]) {
      try {
        child.kill('SIGKILL');
      } catch {
        // The child already exited.
      }
    }
    children.clear();
    await rm(root, { recursive: true, force: true });
  }

  const fixture = {
    dir: root,
    stateDir,
    invocationsDir,
    sessionsDir,
    controlFile,
    executable,
    version: VERSION,
    defaults: CONTROL_DEFAULTS,
    dirExists: () => existsSync(root),
    setControl,
    getControl,
    invocations,
    waitForInvocations,
    waitForIdle,
    sessions,
    readSession,
    run,
    spawn: spawnCli,
    cleanup
  };

  if (t && typeof t.after === 'function' && !options.keep) {
    t.after(async () => {
      await fixture.cleanup();
    });
  }

  return fixture;
}

export default createQoderFixture;
